ALTER TABLE "phone_verification" DROP CONSTRAINT "phone_verification_purpose_known";--> statement-breakpoint
ALTER TABLE "phone_verification" ADD COLUMN "payload" jsonb;--> statement-breakpoint
CREATE UNIQUE INDEX "phone_verification_open_claim_idx" ON "phone_verification" USING btree ("tenant_id","requested_by_type","requested_by_id") WHERE "phone_verification"."status" in ('sent', 'awaiting_manual') and "phone_verification"."purpose" = 'claim';--> statement-breakpoint
ALTER TABLE "phone_verification" ADD CONSTRAINT "phone_verification_claim_complete" CHECK ("phone_verification"."purpose" <> 'claim' or ("phone_verification"."subject_type" = 'customer' and "phone_verification"."tenant_id" is not null and "phone_verification"."phone" is not null and "phone_verification"."requested_by_type" = 'portal_user' and ("phone_verification"."payload" is not null or "phone_verification"."status" not in ('sent', 'awaiting_manual'))));--> statement-breakpoint
ALTER TABLE "phone_verification" ADD CONSTRAINT "phone_verification_payload_open_claim" CHECK ("phone_verification"."payload" is null or ("phone_verification"."purpose" = 'claim' and "phone_verification"."status" in ('sent', 'awaiting_manual')));--> statement-breakpoint
ALTER TABLE "phone_verification" ADD CONSTRAINT "phone_verification_purpose_known" CHECK ("phone_verification"."purpose" in ('signup', 'change', 'claim'));